        resize: vertical;
      }
    </style>

    <script type="importmap">
      {
        "imports": {
          "preact": "https://esm.sh/preact",
          "preact/": "https://esm.sh/preact/",
          "htm/preact": "https://esm.sh/htm/preact?external=preact"
        }
      }
    </script>

    <script type="module">
      import { h, render } from "preact";
      import { useState } from "preact/hooks";
      import { html } from "htm/preact";

      // New component: PostApiPanel
      // This panel appears in the left pane and provides buttons to call POST APIs.
      const PostApiPanel = ({ apiPrefix }) => {
        const [postUri, setPostUri] = useState("");
        const [postBody, setPostBody] = useState("");
        const [response, setResponse] = useState("");
        const [selectedMethod, setSelectedMethod] = useState("");

        // Define available POST methods (expand as needed)
        const methods = [
          {
            label: "Detect Objects",
            uri: `/api/${apiPrefix}/detectObjects`,
            defaultBody: '{"imageUrl": ""}'
          },
          {
            label: "Classify Image",
            uri: `/api/${apiPrefix}/classifyImage`,
            defaultBody: '{"imageUrl": ""}'
          },
          {
            label: "Find Position",
            uri: `/api/${apiPrefix}/findPosition`,
            defaultBody: '{"imageUrl": "", "element": ""}'
          }
        ];

        const sendPostRequest = async () => {
          try {
            const res = await fetch(postUri, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: postBody
            });
            const data = await res.json();
            setResponse(JSON.stringify(data, null, 2));
          } catch (err) {
            setResponse("Error: " + err);
          }
        };

        const sendSetMockResponse = async () => {
          // Here we assume that the API uses the last segment of the URI as the API name.
          // Adjust this as needed.
          if (!selectedMethod) {
            alert("Select an API method first.");
            return;
          }
          const endpoint = `/api/setresponse/${apiPrefix}/${selectedMethod}`;
          try {
            const res = await fetch(endpoint, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: response
            });
            const data = await res.json();
            alert("Mock response set:\n" + JSON.stringify(data, null, 2));
          } catch (err) {
            alert("Error setting mock response: " + err);
          }
        };

        return html`
          <div class="panel">
            <div class="panel-header">
              <h4 class="panel-title">POST API Tester</h4>
            </div>
            <div class="panel-body">
              <div class="btn-group btn-group-block">
                ${methods.map(method => html`
                  <button
                    class="btn"
                    onClick=${() => {
                      setPostUri(method.uri);
                      setPostBody(method.defaultBody);
                      // Extract method name from the URL (e.g., detectObjects)
                      const parts = method.uri.split("/");
                      setSelectedMethod(parts[parts.length - 1]);
                    }}>
                    ${method.label}
                  </button>
                `)}
              </div>
              <div class="form-group">
                <label class="form-label">POST URI</label>
                <textarea
                  class="form-input"
                  rows="2"
                  value=${postUri}
                  onInput=${(e) => setPostUri(e.target.value)}>
                </textarea>
              </div>
              <div class="form-group">
                <label class="form-label">POST Body (JSON)</label>
                <textarea
                  class="form-input"
                  rows="4"
                  value=${postBody}
                  onInput=${(e) => setPostBody(e.target.value)}>
                </textarea>
              </div>
              <div class="btn-group">
                <button class="btn btn-primary" onClick=${sendPostRequest}>
                  Send Request
                </button>
              </div>
              <div class="form-group">
                <label class="form-label">Response (JSON)</label>
                <textarea
                  class="form-input"
                  rows="4"
                  value=${response}
                  onInput=${(e) => setResponse(e.target.value)}>
                </textarea>
              </div>
              <div class="btn-group">
                <button class="btn btn-primary" onClick=${sendSetMockResponse}>
                  Set Mock Response
                </button>
              </div>
            </div>
          </div>
        `;
      };

      // GetImagePanel lets you pull an image from an API endpoint.
      const GetImagePanel = ({ apiPrefix }) => {
        const [width, setWidth] = useState("500");
        const [height, setHeight] = useState("");
        const [imageUrl, setImageUrl] = useState("");
        const [isSnap, setIsSnap] = useState(false);
        const [imageDimensions, setImageDimensions] = useState(null);
        const [apiRequestUrl, setApiRequestUrl] = useState("");

        const getImage = async () => {
          const queryParams = {};
          if (width) queryParams.w = width;
          if (height) queryParams.h = height;
          if (isSnap) queryParams.snap = true;
          const queryString = Object.entries(queryParams)
            .map(([key, value]) => `${key}=${value}`)
            .join("&");
          const url = `/api/${apiPrefix}/getImage` + (queryString ? `?${queryString}` : "");
          setApiRequestUrl(`GET ${url}`);
          const response = await fetch(url);
          const blob = await response.blob();
          if (imageUrl) {
            URL.revokeObjectURL(imageUrl);
          }
          setImageUrl(URL.createObjectURL(blob));
        };

        return html`
          <div class="panel">
            <div class="panel-header">
              <h4 class="panel-title">Get Image</h4>
            </div>
