                `}
              </span>

              ${apiRequestUrl && html`
                <div>
                  <pre class="code label label-secondary">${apiRequestUrl}</pre>
                </div>
              `}
              <div>
                ${imageUrl && html`
                  <img
                    src=${imageUrl}
                    alt="Retrieved image"
                    class="img-fit-contain"
                    style="margin-top: 10px;"
                    onload=${(e) => {
                      setImageDimensions({
                        width: e.target.width,
                        height: e.target.height,
                      });
                    }} />
                `}
              </div>
            </div>
          </div>
        `;
      };

      // SetMockResponsePanel (for getImage, for example)
      const SetMockResponsePanel = ({ apiPrefix }) => {
        const [mockResponseMode, setMockResponseMode] = useState("folder");
        const [mockResponseFolder, setMockResponseFolder] = useState("C:\\Users\\Public\\Pictures\\Sample Pictures");
        const [response, setResponse] = useState("");
        const [apiRequestUrl, setApiRequestUrl] = useState("");
        const [apiJsonBody, setApiJsonBody] = useState("");

        const setGetImageResponse = async () => {
          const url = `/api/${apiPrefix}/setResponse`;
          const r = {
            api: "getImage",
            response: {
              mode: mockResponseMode,
              folder: mockResponseFolder,
            },
          };
          const jsonBody = JSON.stringify(r);
          const response = await fetch(url, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: jsonBody,
          });
          setApiRequestUrl(`POST ${url}`);
          setApiJsonBody(JSON.stringify(r, null, 2));
          const data = await response.text();
          setResponse(JSON.stringify(JSON.parse(data), null, 2));
        };

        return html`
          <div class="panel">
            <div class="panel-header">
              <h4 class="panel-title">Set Mock Response (Get Image)</h4>
            </div>
            <div class="panel-body">
              <div class="form-group">
                <select
                  class="form-select"
                  value=${mockResponseMode}
                  onChange=${(e) => setMockResponseMode(e.target.value)}>
                  <option value="generate">Generated Image</option>
                  <option value="folder">Images from Folder</option>
                </select>
              </div>
              ${mockResponseMode === "folder" && html`
                <div class="form-group">
                  <input
                    class="form-input"
                    type="text"
                    placeholder="Folder name"
                    value=${mockResponseFolder}
                    onInput=${(e) => setMockResponseFolder(e.target.value)} />
                </div>
              `}
              <button class="btn btn-primary" onClick=${setGetImageResponse}>Set Response</button>
              <div>
                ${apiRequestUrl && html`
                  <div>
                    <pre class="code label label-secondary">${apiRequestUrl}</pre>
                  </div>
                  <span class="label label-rounded label-success">Request</span>
                `}
                ${apiJsonBody && html`
                  <div>
                    <pre class="code" data-lang="JSON">${apiJsonBody}</pre>
                  </div>
                `}
              </div>
              <div>
                ${response && html`
                  <span class="label label-rounded label-success">Response</span>
                  <div class="form-group">
                    <pre class="code" data-lang="JSON">${response}</pre>
                  </div>
                `}
              </div>
            </div>
          </div>
        `;
      };

      // Each Vision page now shows a two–column layout.
      // The left column now contains our PostApiPanel,
      // while the right column contains GetImagePanel and SetMockResponsePanel.
      const VisionPage = ({ apiPrefix }) => {
        return html`
          <div class="container">
            <div class="columns">
              <div class="column col-6 col-md-12">
                <${PostApiPanel} apiPrefix=${apiPrefix} />
              </div>
              <div class="column col-6 col-md-12">
                <${GetImagePanel} apiPrefix=${apiPrefix} />
                <${SetMockResponsePanel} apiPrefix=${apiPrefix} />
              </div>
            </div>
          </div>
        `;
      };

      // Our main tester renders several vision API tabs.
      const ApiTester = () => {
        const [activeTab, setActiveTab] = useState(0);
        const tabData = [
          { title: "Vision 1", apiPrefix: "vision1" },
          { title: "Vision 2", apiPrefix: "vision2" },
          { title: "Vision 3", apiPrefix: "vision3" },
          { title: "Vision 4", apiPrefix: "vision4" },
          { title: "Vision 5", apiPrefix: "vision5" },
          { title: "Vision System", apiPrefix: "visionSystem" }
        ];

        const handleTabClick = (index) => {
          setActiveTab(index);
        };

        return html`
          <h3>Vision API Test</h3>
          <div class="container">
            <div class="tabs">
              <ul class="tab">
                ${tabData.map((tab, index) => html`
                  <li
                    class=${"tab-item " + (index === activeTab ? "active" : "")}
                    onClick=${() => handleTabClick(index)}>
                    <a href="#">${tab.title}</a>
                  </li>
                `)}
              </ul>
            </div>
            ${tabData.map((tab, index) => html`
              <div style=${{ display: index === activeTab ? "block" : "none" }}>
                <${VisionPage} apiPrefix=${tab.apiPrefix} />
              </div>
            `)}
          </div>
        `;
      };

      render(h(ApiTester), document.body);
    </script>
  </head>
  <body></body>
</html>
