      function removeFromTaskbar(win) {
        if (win.taskbarIcon && win.taskbarIcon.parentElement) {
          win.taskbarIcon.parentElement.removeChild(win.taskbarIcon);
        }
      }

      // Makes the given element draggable by clicking and holding on the specified handle.
      function makeDraggable(el, handle) {
        var offsetX = 0, offsetY = 0, isDragging = false;

        handle.addEventListener('mousedown', function(e) {
          isDragging = true;
          offsetX = el.offsetLeft - e.clientX;
          offsetY = el.offsetTop - e.clientY;
          el.classList.add('dragging');
        });

        document.addEventListener('mouseup', function() {
          isDragging = false;
          el.classList.remove('dragging');
        });

        document.addEventListener('mousemove', function(e) {
          if (isDragging) {
            el.style.left = (e.clientX + offsetX) + 'px';
