    <script>
    let currentZIndex = 1;

    // File System Simulation
    const fileSystem = {
        currentPath: '/',
        directories: {
            '/': {
                files: { 'file1.txt': 'Initial content', 'file2.txt': 'Second file' },
                folders: ['Documents']
            },
            '/Documents': {
                files: { 'report.txt': 'Document content' },
                folders: []
            }
        }
    };

    // Window creation
    function createWindow(title, className) {
        const windowDiv = document.createElement('div');
        windowDiv.className = `window ${className}`;
        windowDiv.style.position = 'absolute';
        windowDiv.style.left = '50px';
        windowDiv.style.top = '50px';

        const titleBar = document.createElement('div');
        titleBar.className = 'title-bar';
        titleBar.innerHTML = `
            <div class="title-text">${title}</div>
            <div class="close-button" onclick="closeWindow(this.parentNode.parentNode)">X</div>
        `;

        const contentDiv = document.createElement('div');
        contentDiv.className = 'window-content';
        contentDiv.style.padding = '10px';

        windowDiv.appendChild(titleBar);
        windowDiv.appendChild(contentDiv);
        document.getElementById('desktop').appendChild(windowDiv);
        return windowDiv;
    }

    // Window management
    function closeWindow(element) {
        element.remove();
    }

    function bringToFront(element) {
        element.style.zIndex = ++currentZIndex;
    }

    // Drag functionality
    function makeDraggable(element) {
        let pos1 = 0, pos2 = 0, pos3 = 0, pos4 = 0;
        element.querySelector('.title-bar').onmousedown = dragMouseDown;

        function dragMouseDown(e) {
            e = e || window.event;
            e.preventDefault();
            pos3 = e.clientX;
            pos4 = e.clientY;
            document.onmouseup = closeDrag;
            document.onmousemove = elementDrag;
        }

        function elementDrag(e) {
            e = e || window.event;
            e.preventDefault();
            pos1 = pos3 - e.clientX;
            pos2 = pos4 - e.clientY;
            pos3 = e.clientX;
            pos4 = e.clientY;
            const left = (element.offsetLeft - pos1);
            const top = (element.offsetTop - pos2);
            element.style.left = left + "px";
            element.style.top = top + "px";
        }

        function closeDrag() {
            document.onmouseup = null;
            document.onmousemove = null;
        }
    }

    // Text Editor
    function openTextEditor() {
        const existing = document.querySelector('.text-editor');
        if (existing) { bringToFront(existing); return; }
        const window = createWindow('Text Editor', 'text-editor');
        const content = window.querySelector('.window-content');
        content.innerHTML = `
            <textarea id="text-editor-area" style="width: 100%; height: 150px;"></textarea>
            <button onclick="saveFile()">Save</button>
        `;
        makeDraggable(window);
        bringToFront(window);
    }

    function saveFile() {
        const content = document.querySelector('#text-editor-area').value;
        const fileName = prompt('Enter file name:');
        const currentDir = fileSystem.directories[fileSystem.currentPath];
        currentDir.files[fileName] = content;
    }

    // Calculator
    function openCalculator() {
        const existing = document.querySelector('.calculator');
        if (existing) { bringToFront(existing); return; }
        const window = createWindow('Calculator', 'calculator');
        const content = window.querySelector('.window-content');
        content.innerHTML = `
            <input type="text" id="calculator-display" disabled>
            <div class="calculator-row">
                <button onclick="calcInput('7')">7</button>
                <button onclick="calcInput('8')">8</button>
                <button onclick="calcInput('9')">9</button>
                <button onclick="calcInput('/')">/</button>
            </div>
            <div class="calculator-row">
                <button onclick="calcInput('4')">4</button>
                <button onclick="calcInput('5')">5</button>
                <button onclick="calcInput('6')">6</button>
                <button onclick="calcInput('*')">*</button>
            </div>
            <div class="calculator-row">
                <button onclick="calcInput('1')">1</button>
                <button onclick="calcInput('2')">2</button>
                <button onclick="calcInput('3')">3</button>
                <button onclick="calcInput('-')">-</button>
            </div>
            <div class="calculator-row">
                <button onclick="calcInput('0')">0</button>
                <button onclick="calcInput('.')">.</button>
                <button onclick="calcInput('+')">+</button>
                <button onclick="calculate()">=</button>
            </div>
        `;
        makeDraggable(window);
        bringToFront(window);
    }

    let calcDisplay = '';
    function calcInput(value) {
        calcDisplay += value;
        document.getElementById('calculator-display').value = calcDisplay;
    }

    function calculate() {
        try {
            const result = eval(calcDisplay);
            document.getElementById('calculator-display').value = result;
            calcDisplay = result.toString();
        } catch (e) {
            alert('Invalid expression');
            calcDisplay = '';
        }
    }

    // File Explorer
    function openFileExplorer() {
        const existing = document.querySelector('.file-explorer');
        if (existing) { bringToFront(existing); return; }
        const window = createWindow('File Explorer', 'file-explorer');
        displayFiles(window);
        makeDraggable(window);
        bringToFront(window);
    }

    function displayFiles(window) {
        const content = window.querySelector('.window-content');
        content.innerHTML = '<div id="file-list"></div>';

        const currentDir = fileSystem.directories[fileSystem.currentPath];
        const fileList = document.getElementById('file-list');

        // Add back option
        if(fileSystem.currentPath !== '/') {
            const backItem = document.createElement('div');
            backItem.className = 'folder';
            backItem.textContent = '..';
            backItem.onclick = () => {
                const newPath = fileSystem.currentPath.slice(0, fileSystem.currentPath.lastIndexOf('/'));
                fileSystem.currentPath = newPath;
                displayFiles(window);
            };
            fileList.appendChild(backItem);
        }

        // Add folders
        currentDir.folders.forEach(folder => {
            const item = document.createElement('div');
            item.className = 'folder';
            item.textContent = folder;
            item.onclick = () => {
                fileSystem.currentPath += '/' + folder;
                displayFiles(window);
            };
            fileList.appendChild(item);
        });

        // Add files
        Object.keys(currentDir.files).forEach(file => {
            const item = document.createElement('div');
            item.className = 'file';
            item.textContent = file;
            item.onclick = () => {
                const editorWindow = createWindow(file, 'file-viewer');
                const contentDiv = editorWindow.querySelector('.window-content');
                contentDiv.innerHTML = `<pre>${currentDir.files[file]}</pre>`;
                makeDraggable(editorWindow);
            };
            fileList.appendChild(item);
        });
    }
    </script>
</body>
</html>
```

This code creates a basic operating system emulator with:

1. A taskbar with icons for 3 apps
2. Draggable windows with close buttons
3. Text editor with save functionality
4. Calculator that handles basic arithmetic
5. File explorer showing files and folders with:
   - Directory navigation
   - File preview windows
   - Simple file system structure

To use:

1. Click taskbar icons to open apps
2. Drag windows by their title bars
3. Use the file explorer to navigate directories and view files
4. The calculator supports basic operations
5. The text editor allows saving files to the simulated file system

The file system simulation is very basic and stored in memory. You can modify the `fileSystem` object to add more files and directories.

