@Service
public class AccountService {

    @Autowired
    private List<AccountRepository<? extends Account>> repositories;

    public Account getAccountById(Integer id) {
        for (AccountRepository<? extends Account> repo : repositories) {
            if (repo.existsById(id)) {
                return repo.findById(id).orElse(null);
            }
        }
        return null;
    }
}
