        }
    }
    playerXArray.push(Player.x);
    playerYArray.push(Player.y);
    var delay = floor(random(5, 50));
    if (AI.x < playerXArray[max(0, frameCount-delay)]) {
        AI.x += speed;
    }
    if (AI.x > playerXArray[max(0, frameCount-delay)]) {
        AI.x -= speed;
    }
    if (AI.y < playerYArray[max(0, frameCount-delay)]) {
        AI.y += speed;
    }
    if (AI.y > playerYArray[max(0, frameCount-delay)]) {
        AI.y -= speed;
    }

    if (Player.x > AI.x - 50 && Player.x < AI.x + 50 && Player.y > AI.y - 50 && Player.y < AI.y + 50) {
        Program.restart();
    }
}

function chooseIt() {
    playerPositions[floor(random(playerPositions.length))].it = true;
}

var coin = {x: random(100, 500), y: random(100, 500)};
var score = 0;
function coinCollision() {
    fill(255, 255, 0);
    rect(coin.x, coin.y, 25, 25);
    if (playerPositions[0].x > coin.x - 50 && playerPositions[0].x < coin.x + 25 && playerPositions[0].y > coin.y - 50 && playerPositions[0].y < coin.y + 25) {
        score++;
        coin = {x: random(100, 500), y: random(100, 500)};
    }
}

chooseIt();

function draw() {
    background(255);
    drawPlayers();
    movePlayers();
    coinCollision();
    text(score, 200, 200);
}

