      .toggle::before {
        content: '+';
        font-weight: bold;
        font-size: 16px;
      }
      .toggle.expanded::before {
        content: '-';
      }
      :host ::slotted([slot="header"]) {
        font-size: 1.2em;
        margin-left: 8px;
      }
      .intro {
        margin: 1rem 0 0.5rem;
      }
      .details {
        padding-left: 32px;
