      }
      .expand-button {
        margin-top: 0.5rem;
        padding: 0.3rem 0.8rem;
        background: #007bff;
        color: white;
        border: none;
        border-radius: 4px;
        cursor: pointer;
        transition: background 0.2s;
      }
      .expand-button:hover {
        background: #0056b3;
      }
    `;

    const template = document.createElement('template');
    template.innerHTML = `
      <style>${style}</style>
      <div class="header-container">
        <div class="toggle" role="button" tabindex="0"></div>
        <slot name="header"></slot>
      </div>
      <div class="intro">
        <slot name="intro"></slot>
      </div>
      <div class="details" hidden>
        <slot name="details"></slot>
      </div>
      <button class="expand-button">Expand more</button>
    `;

    this.shadowRoot.appendChild(template.content.cloneNode(true));

    this.toggleEl = this.shadowRoot.querySelector('.toggle');
    this.detailsDiv = this.shadowRoot.querySelector('.details');
    this.expandButton = this.shadowRoot.querySelector('.expand-button');

    this.updateUI();
    this.toggleEl.addEventListener('click', this.toggle.bind(this));
    this.toggleEl.addEventListener('keydown', this.handleKey.bind(this));
    this.expandButton.addEventListener('click', this.toggle.bind(this));
  }

  toggle() {
    this.expanded = !this.expanded;
    this.updateUI();
  }

  handleKey(event) {
    if (event.key === 'Enter' || event.key === ' ') {
      this.toggle();
      event.preventDefault();
    }
  }

  updateUI() {
    this.toggleEl.classList.toggle('expanded', this.expanded);
    this.detailsDiv.hidden = !this.expanded;
    this.expandButton.hidden = this.expanded;
  }
}

customElements.define('x-details', XDetails);
```

