            audioRecorder = try AVAudioRecorder(url: audioFilename, settings: settings)
            audioRecorder?.prepareToRecord()
            audioRecorder?.record()
            audioRecorder?.isMeteringEnabled = true
        } catch {
            print("Error starting recording: \(error)")
        }
    }

    func stopRecording() -> URL? {
        audioRecorder?.stop()
        let url = audioRecorder?.url
        audioRecorder = nil
        return url
    }

    private func getDocumentsDirectory() -> URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
    }

    func getAveragePower() -> Float {
        audioRecorder?.updateMeters()
        return audioRecorder?.averagePower(forChannel: 0) ?? -160
    }
}

// ViewModel for state management
class RecordingViewModel: ObservableObject {
    @Published var isRecording = false
    @Published var equalizerLevels = [CGFloat](repeating: 0.0, count: 5)
    @Published var recordedURL: URL?

    private var timer: Timer?
    private let audioManager = AudioManager.shared

    let timerInterval: TimeInterval = 0.05 // Adjust for sensitivity

    func startRecording() {
        isRecording = true
        audioManager.startRecording()
        startTimer()
    }

    func stopRecording() {
        isRecording = false
        if let url = audioManager.stopRecording() {
            recordedURL = url
        }
        stopTimer()
    }

    private func startTimer() {
        timer?.invalidate()
        timer = Timer.scheduledTimer(withTimeInterval: timerInterval, repeats: true) { [weak self] _ in
            guard let self = self else { return }
            let level = self.audioManager.getAveragePower()
            let normalizedLevel = self.normalizeLevel(level)

            // Create wave effect
            self.equalizerLevels.removeLast()
            self.equalizerLevels.insert(normalizedLevel, at: 0)
        }
    }

    private func stopTimer() {
        timer?.invalidate()
        timer = nil
    }

    private func normalizeLevel(_ level: Float) -> CGFloat {
        let normalized = (level - -160) / (0 - (-160))
        return CGFloat(max(0, min(1, normalized)))
    }
}

