Here's the Unity geometry shader code that creates quads for non-transparent pixels and extrudes them along the Z-axis:

```csharp
Shader "Custom/TransparentPixelQuads" {
    Properties {
        _MainTex ("Texture", 2D) = "white" {}
        _Extrusion ("Extrusion Factor", Float) = 1.0
    }

    SubShader {
        Tags {"Queue"="Transparent" "RenderType"="Transparent"}
        Pass {
            CGPROGRAM
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag
            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _Extrusion;

            struct appdata {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2g {
                float4 pos : SV_POSITION;
                float2 uv : TEXCOORD0;
                float4 objPos : TEXCOORD1; // Object space position
            };

            v2g vert (appdata v) {
                v2g o;
                o.pos = UnityObjectToClipPos(v.vertex);
                o.uv = v.uv;
                o.objPos = v.vertex; // Store object space position
                return o;
            }

            struct geomOutput {
                float4 pos : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            [maxvertexcount(6)]
            void geom (point v2g input[1], inout TriangleStream<geomOutput> tristream) {
                // Sample texture at the UV coordinate
                float4 color = tex2Dlod(_MainTex, float4(input[0].uv, 0, 0));
                if (color.a < 0.5) {
                    return;
                }

                // Get world position of the vertex
                float3 worldPos = mul(unity_ObjectToWorld, float4(input[0].objPos.xyz, 1.0)).xyz;

                // Calculate the size of the quad (1 unit in XY)
                float size = 1.0;

                // Define the four corners of the base and extruded positions
                float3 v1 = worldPos - float3(size * 0.5, size * 0.5, 0);
                float3 v2 = worldPos + float3(size * 0.5, -size * 0.5, 0);
                float3 v3 = worldPos - float3(size * 0.5, size * 0.5, _Extrusion);
                float3 v4 = worldPos + float3(size * 0.5, -size * 0.5, _Extrusion);

                // Emit two triangles forming the extruded rectangle
                geomOutput o;

                // First triangle (base to extrusion)
                o.pos = mul(UNITY_MATRIX_VP, float4(v1, 1));
                o.uv = input[0].uv;
                tristream.Append(o);
                o.pos = mul(UNITY_MATRIX_VP, float4(v2, 1));
                tristream.Append(o);
                o.pos = mul(UNITY_MATRIX_VP, float4(v3, 1));
                tristream.Append(o);

                // Second triangle
                o.pos = mul(UNITY_MATRIX_VP, float4(v2, 1));
                tristream.Append(o);
                o.pos = mul(UNITY_MATRIX_VP, float4(v4, 1));
                tristream.Append(o);
                o.pos = mul(UNITY_MATRIX_VP, float4(v3, 1));
                tristream.Append(o);
            }

            fixed4 frag (geomOutput i) : SV_Target {
                fixed4 col = tex2D(_MainTex, i.uv);
                return col;
            }

            ENDCG
        }
    }
}
```

**Important Notes:**
1. **Mesh Setup**: The mesh must be a grid of points where each vertex corresponds to a pixel. The vertices should be arranged in object space such that each vertex's position (e.g., `(i, j, 0)`) aligns with the pixel indices. Use a script to generate this grid mesh.
2. **Material Settings**: Assign the material to the mesh and ensure the mesh is rendered as points in the Unity material settings.
3. **Extrusion Direction**: The quads are extruded along the Z-axis. Modify the `v3` and `v4` calculations to change the extrusion direction.
4. **Scaling**: Adjust the `size` variable in the geometry shader to control the size of the quads.

This shader creates 3D quads for non-transparent pixels, extruding them along the Z-axis. Each quad is formed by two triangles, creating a rectangular prism effect.

