<?php

use Carbon\Carbon;

if (!function_exists('calculateProcessDates')) {
    /**
     * Calculate process start and end dates.
     *
     * @param  string  $orderCreatedDate  The order creation date as string (e.g. "25/06/2024 10:45 AM")
     * @param  array   $processes         Array of process definitions. Each process should include at least completed_days.
     * @return array                      Returns the processes array with the computed start_date and end_date.
     */
    function calculateProcessDates($orderCreatedDate, array $processes)
    {
        // Convert order created date to a Carbon instance. Adjust the format according to your date string format.
        $orderCreated = Carbon::createFromFormat('d/m/Y h:i A', $orderCreatedDate);

        foreach ($processes as $index => &$process) {
            // For the first process, use the order created date as start_date.
            if ($index === 0) {
                $startDate = $orderCreated;
            } else {
                // For subsequent processes, parse the previous process's computed end_date.
                $startDate = Carbon::createFromFormat('d/m/Y h:i A', $processes[$index - 1]['end_date']);
            }

            // Set start_date for the current process in desired format.
            $process['start_date'] = $startDate->format('d/m/Y h:i A');

            // Calculate the end_date by adding the completed_days.
            // The completed_days field is used to add whole days.
            $endDate = $startDate->copy()->addDays($process['completed_days']);
            $process['end_date'] = $endDate->format('d/m/Y h:i A');
        }

        return $processes;
    }
}

