```php
use Carbon\Carbon;

public function calculateProcessDates($orderCreatedDate, $processes) {
    // Sort processes by sequence number
    usort($processes, function($a, $b) {
        return $a['sequence'] - $b['sequence'];
    });

    $currentStartDate = Carbon::parse($orderCreatedDate);

    foreach ($processes as &$process) {
        // Set start date for current process
        $process['start_date'] = $currentStartDate;

        // Calculate end date by adding completed days
        $process['end_date'] = clone $currentStartDate->addDays($process['completed_days']);

        // Update currentStartDate for next process
        $currentStartDate = $process['end_date'];
    }

    return $processes;
}
```

