```python
import sys

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def next_prime(current):
    n = current + 1
    while not is_prime(n):
        n += 1
    return n

def main():
    tasks = []
    current_prime = 2  # Starting with the first prime

    while True:
        print("\nOptions:")
        print("1. Add a task")
        print("2. Mark task as completed")
        print("3. List tasks")
        print("4. Exit")

        choice = input("Enter choice (1-4): ")

        if choice == '1':
            task_text = input("Enter task: ").strip()
            if task_text:
                tasks.append({'task': task_text, 'completed': False, 'prime_number': None})
            else:
                print("Task cannot be empty.")

        elif choice == '2':
            if not tasks:
                print("No tasks to mark.")
                continue

            print("Current tasks:")
            list_tasks(tasks)

            number = input("Enter task number to mark as completed: ")
            if not number.isdigit():
                print("Invalid input.")
                continue
            number = int(number)
            task_index = number - 1

            if task_index < 0 or task_index >= len(tasks):
                print("Invalid task number.")
                continue

            task = tasks[task_index]
            if task['completed']:
                print("Task is already completed.")
            else:
                task['completed'] = True
                task['prime_number'] = current_prime
                current_prime = next_prime(current_prime)
                print("Task marked as completed!")

        elif choice == '3':
            list_tasks(tasks)

        elif choice == '4':
            print("Exiting...")
            sys.exit()

        else:
            print("Invalid choice.")

def list_tasks(tasks):
    if not tasks:
        print("No tasks.")
        return

    for idx, task in enumerate(tasks):
        if task['completed']:
            number = task['prime_number']
        else:
            number = idx + 1
        status = " [Completed]" if task['completed'] else ""
        print(f"{number}. {task['task']}{status}")

if __name__ == "__main__":
    main()
```

### Key Features:
1. **Prime Number Tracking:** Completed tasks are marked with prime numbers in sequential order (2, 3, 5, 7...)
2. **Natural Number Display:** Incomplete tasks are displayed with natural numbers (1, 2, 3...)
3. **User Interface:** Simple menu-based interface with options to add tasks, mark completion, list tasks, and exit
4. **Validation:** Checks for valid inputs and prevents marking already completed tasks

### Usage:
1. Choose option 1 to add tasks
2. Choose option 3 to view tasks with their status
3. Choose option 2 to mark tasks by their displayed number
4. Choose option 4 to exit

The completed tasks will always show their assigned prime number while incomplete tasks show their position in the list. The prime numbers are assigned in order of completion, not their position in the list.

