<?php

namespace Drupal\my_module\Plugin\Block;

use Drupal\Core\Block\BlockBase;
use Drupal\Core\Link;
use Drupal\Core\Url;
use Drupal\node\Entity\Node;
use Drupal\Core\Entity\EntityTypeManagerInterface;
use Symfony\Component\DependencyInjection\ContainerInterface;
use Drupal\Core\Plugin\ContainerFactoryPluginInterface;

/**
 * Provides a 'Article Teaser List' Block.
 *
 * @Block(
 *   id = "article_teaser_list_block",
 *   admin_label = @Translation("Article Teaser List"),
 * )
 */
class ArticleTeaserListBlock extends BlockBase implements ContainerFactoryPluginInterface {

  /**
   * The entity type manager service.
   *
   * @var \Drupal\Core\Entity\EntityTypeManagerInterface
   */
  protected $entityTypeManager;

  /**
   * Constructs a new ArticleTeaserListBlock.
   *
   * @param array $configuration
   *   A configuration array containing information about the plugin instance.
   * @param string $plugin_id
   *   The plugin_id for the plugin instance.
   * @param mixed $plugin_definition
   *   The plugin implementation definition.
   * @param \Drupal\Core\Entity\EntityTypeManagerInterface $entity_type_manager
   *   The entity type manager.
   */
  public function __construct(array $configuration, $plugin_id, $plugin_definition, EntityTypeManagerInterface $entity_type_manager) {
    parent::__construct($configuration, $plugin_id, $plugin_definition);
    $this->entityTypeManager = $entity_type_manager;
  }

  /**
   * {@inheritdoc}
   */
  public static function create(ContainerInterface $container, array $configuration, $plugin_id, $plugin_definition) {
    return new static(
      $configuration,
      $plugin_id,
      $plugin_definition,
      $container->get('entity_type.manager')
    );
  }

  /**
   * {@inheritdoc}
   */
  public function build() {
    // Step 1. Load the taxonomy term with name 'foobar'.
    // Adjust the storage properties if needed (e.g., add vocabulary criteria if necessary).
    $term_storage = $this->entityTypeManager->getStorage('taxonomy_term');
    $terms = $term_storage->loadByProperties(['name' => 'foobar']);
    if (empty($terms)) {
      // No matching taxonomy term found.
      return [
        '#markup' => $this->t('No articles found'),
      ];
    }
    $term = reset($terms);
    $term_id = $term->id();

    // Step 2. Build an entity query to get published article nodes tagged with 'foobar'.
    $query = $this->entityTypeManager->getStorage('node')->getQuery();
    $query->condition('type', 'article')
      ->condition('status', 1)
      // Use the taxonomy reference field condition. Ensure the field name is correct.
      ->condition('field_tags.target_id', $term_id)
      ->sort('created', 'DESC')
      ->range(0, 10);
    $nids = $query->execute();

    // Step 3. If no nodes are returned, display a friendly message.
    if (empty($nids)) {
      return [
        '#markup' => $this->t('No articles found'),
      ];
    }
    $nodes = $this->entityTypeManager->getStorage('node')->loadMultiple($nids);

    // Step 4. Use the node view builder to render each node in the 'teaser' view mode.
    $view_builder = $this->entityTypeManager->getViewBuilder('node');
    $items = [];
    foreach ($nodes as $node) {
      $teaser = $view_builder->view($node, 'teaser');

      // Wrap each teaser output in a container with Bootstrap 5's list-group-item class.
      $items[] = [
        '#type' => 'container',
        '#attributes' => ['class' => ['list-group-item']],
        'content' => $teaser,
      ];
    }

    // Step 5. Wrap all items within a container that has the Bootstrap 5 list-group class.
    $build = [
      '#type' => 'container',
      '#attributes' => ['class' => ['list-group']],
      'items' => $items,
      '#attached' => [
        // Be sure that your theme or library includes Bootstrap 5.
        'library' => [
          'my_module/bootstrap5',  // Optionally attach your custom library if needed.
        ],
      ],
    ];

    return $build;
  }

}

--------------------------------------------------

Explanation:

1. Loading the Taxonomy Term:
   • We load the taxonomy term with name "foobar" using loadByProperties(). Adjust this lookup if you need to limit by vocabulary ID.

2. Entity Query:
   • We build an entity query for nodes with type "article" that are published (status = 1).
   • The query filters nodes based on the taxonomy reference field “field_tags” (adjust the field name if yours is different) matching the term ID.
   • Results are sorted by creation date descending and limited to 10.

3. Rendering:
   • Using the node view builder, we render each node in the “teaser” view mode.
   • Each teaser is wrapped in a container styled with Bootstrap’s “list-group-item” class.
   • All items are wrapped in a container with the “list-group” class.

4. Bootstrap Attachments:
   • Optionally, you can attach a custom library (or ensure your theme) loads Bootstrap 5. Modify the library name as needed.

This implementation uses dependency injection for the entity type manager, adheres to Drupal 9 coding standards, and incorporates Bootstrap 5 markup for an efficient and flexible results display.

