```php
// In your custom controller class:

use Drupal\Core\Controller\ControllerBase;
use Drupal\Core\Entity\EntityStorageException;
use Drupal\Core\Session\AccountInterface;

class FoobarArticleController extends ControllerBase {

  /**
   * Displays a list of article nodes tagged with 'foobar'.
   *
   * @return array
   *   Render array for the node list.
   */
  public function foobarArticles() {
    // Load the taxonomy term by name
    $term_storage = \Drupal::entityTypeManager()->getStorage('taxonomy_term');
    $terms = $term_storage->loadByProperties(['name' => 'foobar']);

    if (empty($terms)) {
      return [];
    }

    $term = reset($terms);
    $term_id = $term->id();

    // Efficient entity query for article nodes with the term
    $query = \Drupal::entityQuery('node')
      ->condition('type', 'article')
      ->condition('field_tags.target_id', $term_id)
      // Add access check
      ->accessCheck(TRUE)
      ->sort('created', 'DESC');

    $nids = $query->execute();

    if (empty($nids)) {
      return [];
    }

    // Load nodes and filter by access
    $nodes = Node::loadMultiple($nids);
    $nodes = node_access_filter_nodes($nodes, 'view');

    // Prepare render array with Bootstrap styling
    $build = [
      '#theme' => 'container',
      '#attributes' => ['class' => ['row']],
      '#attached' => [
        'library' => [
          // Replace with your Bootstrap library
          'your_theme/bootstrap',
        ],
      ],
    ];

    foreach ($nodes as $node) {
      // Render teaser view mode
      $teaser = \Drupal::entityTypeManager()
        ->getViewBuilder('node')
        ->view($node, 'teaser');

      // Wrap teaser in Bootstrap card
      $build['cards'][] = [
        '#type' => 'container',
        '#attributes' => ['class' => ['col-md-4', 'mb-3']],
        'card' => [
          '#type' => 'container',
          '#attributes' => ['class' => ['card']],
          'body' => $teaser,
        ],
      ];
    }

    return $build;
  }
}
