    apiVersion: "apps/v1"
    kind: "Deployment"
    metadata: {
        name: $name
        labels: {app: $app}
    }
    spec: {
        replicas: 1
        selector: {matchLabels: {app: $app}}
        template: {
            metadata: {labels: {app: $app}}
            spec: {
