    name: "homeassistant-deployment"
    app: apps.homeassistant.name
    containers: [
        {
            name: apps.homeassistant.name
            image: "homeassistant/home-assistant:latest"
            ports: [{containerPort: apps.homeassistant.port}]
            env: [{
                name: "HOMEASSISTANT__FRONTEND__SSL"
                value: "false"
            }]
        }
    ]
}

# Nginx Deployment
nginxDeployment: deployment {
    name: "nginx-deployment"
    app: apps.nginx.name
    containers: [
        {
            name: apps.nginx.name
            image: "nginx:latest"
            ports: [{containerPort: apps.nginx.port}]
            volumeMounts: [{
                name: "nginx-config"
                mountPath: "/etc/nginx/conf.d/default.conf"
                subPath: "default.conf"
            }]
        }
    ]
    spec.template.spec.volumes: [{
        name: "nginx-config"
        configMap: {name: "nginx-config"}
    }]
}

# Nginx Configuration
nginxConfig: {
    apiVersion: "v1"
    kind: "ConfigMap"
    metadata: {name: "nginx-config"}
    data: {
        "default.conf": """
        server {
            listen 80;
            server_name example.com;

            location / {
                proxy_pass http://homeassistant-service:#apps.homeassistant.port;
                proxy_set_header Host $host;
                proxy_set_header X-Real-IP $remote_addr;
                proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            }
        }
        """
    }
}

# Service Definitions
service: {
    apiVersion: "v1"
    kind: "Service"
    metadata: {name: $name}
    spec: {
        selector: {app: $app}
        ports: [{
            protocol: "TCP"
            port: $port
            targetPort: $port
        }]
        type: $type
    }
}

homeassistantService: service {
    name: "homeassistant-service"
    app: apps.homeassistant.name
    port: apps.homeassistant.port
    type: "ClusterIP"
}

nginxService: service {
    name: "nginx-service"
    app: apps.nginx.name
    port: apps.nginx.port
    type: "NodePort"
}

# Cluster Composition
cluster: [
    homeassistantDeployment,
    nginxDeployment,
    nginxConfig,
    homeassistantService,
    nginxService,
]
