    // 从最低位（字符串末尾）开始逐位相加
    for(int i = len - 1; i >= 0; i--){
        // 将字符转换为数字并加上carry
        int sum = (a[i]-'0') + carry;
        result[pos] = sum % 10;  // 当前位置的数字
        carry = sum / 10;        // 新的进位
        pos++;
    }

    // 如果还有进位，则继续处理
    if(carry > 0){
        while(carry > 0){
            result[pos++] = carry % 10;
            carry /= 10;
        }
    }

    // 输出结果，注意result数组存的是逆序，需要逆序输出
    for(int i = pos - 1; i >= 0; i--){
        cout << result[i];
    }

    return 0;
}

