    add_strategy(strategies, 4, 275)        # 全列
    add_strategy(strategies, 6, 275)        # 小十字
    add_strategy(strategies, 2, 275)        # 另一个4x3
    add_strategy(strategies, 3, 2375)       # 另一个5x5
