    add_strategy(strategies, 5, 275)        # 全行（可能超出行数，需注意）
    add_strategy(strategies, 7, 25)         # 三行覆盖
    add_strategy(strategies, 8, 325, 2, 2)  # 十字策略
    add_strategy(strategies, 8, 275, 3, 5)  # 另一个十字策略
    add_strategy(strategies, 8, 2735, 2, 4) # 另一个十字策略
    add_strategy(strategies, 9, 325)        # 复制策略

    x = LpVariable.dicts("strategy", [(i, j, s) for i in range(1, MAP_HEIGHT + 1)
                                     for j in range(1, MAP_WIDTH + 1)
                                     for s in strategies.keys()], cat='Binary')

    copy_coverage = {}
    if consider_copy_strategy:
        copy_coverage = LpVariable.dicts("copy_coverage",
                                         [(i, j, s, str(strategy_count)) for i in range(1, MAP_HEIGHT + 1)
                                          for j in range(1, MAP_WIDTH + 1)
                                          for s in strategies.keys() if s != str(strategy_count)],
                                         cat='Binary')

    # 目标函数
    prob += lpSum([strategies[s]["cost"] * x[i, j, s] for i in range(1, MAP_HEIGHT + 1)
                   for j in range(1, MAP_WIDTH + 1)
                   for s in strategies.keys()])

    # 约束条件
    for point in points_to_cover:
        if point not in obstacles:
            i, j = map(int, point.split('-'))
            coverage_constraint = 0

            # 原策略的覆盖
            for s in strategies.keys():
                if s != str(strategy_count):
                    for i_s in range(1, MAP_HEIGHT + 1):
                        for j_s in range(1, MAP_WIDTH + 1):
                            if (i - i_s, j - j_s) in strategies[s]["coverage"]:
                                coverage_constraint += x[i_s, j_s, s]

            # 复制策略的覆盖
            if consider_copy_strategy:
                for s in strategies.keys():
                    if s != str(strategy_count):
                        for i_s in range(1, MAP_HEIGHT + 1):
                            for j_s in range(1, MAP_WIDTH + 1):
                                if (i - i_s, j - j_s) in strategies[s]["coverage"]:
                                    coverage_constraint += copy_coverage[i_s, j_s, s, str(strategy_count)]

            prob += coverage_constraint >= 1

    # 障碍物约束
    for obstacle in obstacles:
        i, j = map(int, obstacle.split('-'))
        for s in strategies.keys():
            prob += x[i, j, s] == 0

    # 每个策略只能放置一次
    for s in strategies.keys():
        prob += lpSum([x[i, j, s] for i in range(1, MAP_HEIGHT + 1)
                       for j in range(1, MAP_WIDTH + 1)]) <= 1

        if consider_copy_strategy and s == str(strategy_count):
            for i in range(1, MAP_HEIGHT + 1):
                for j in range(1, MAP_WIDTH + 1):
                    prob += lpSum([copy_coverage[i, j, s_orig, s] for s_orig in strategies.keys() if s_orig != s]) == x[i, j, s]

            for s_orig in strategies.keys():
                if s_orig != s:
                    prob += lpSum([copy_coverage[i, j, s_orig, s] for i in range(1, MAP_HEIGHT + 1)
                                   for j in range(1, MAP_WIDTH + 1)]) <= lpSum([x[i_s, j_s, s_orig] for i_s in range(1, MAP_HEIGHT + 1)
                                                                                for j_s in range(1, MAP_WIDTH + 1)])

    prob.solve()

    print("Status:", LpStatus[prob.status])
    if LpStatus[prob.status] == "Optimal":
        print("火苗花费 =", value(prob.objective))
        for s in strategies.keys():
            if s != str(strategy_count):
                for i in range(1, MAP_HEIGHT + 1):
                    for j in range(1, MAP_WIDTH + 1):
