Here's a step-by-step guide to create character movement on any surface in Unity 2023, including rotation based on the surface normal:

### Step 1: Set Up the Character GameObject
1. **Create a new GameObject** (Cube/Capsule/Sphere) for the character.
2. **Add a Rigidbody** component to handle physics. Set **Use Gravity** to `True`.
3. **Add a Collider** (Capsule/Cube) to detect collisions.

### Step 2: Create the Movement Script
Attach this script to the character GameObject:

```csharp
using UnityEngine;

public class SurfaceMovement : MonoBehaviour
{
    public float moveSpeed = 5f;
    public float rotationSpeed = 5f;

    private Rigidbody rb;
    private Vector3 movementDirection;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
    }

    void FixedUpdate()
    {
        ContactPoint[] contacts = new ContactPoint[10];
        int numContacts = rb.GetContacts(contacts);

        if (numContacts > 0)
        {
            Vector3 normal = contacts[0].normal;

            // Get input direction
            float horizontal = Input.GetAxis("Horizontal");
            float vertical = Input.GetAxis("Vertical");
            Vector3 inputDirection = new Vector3(horizontal, 0, vertical);
            inputDirection = transform.TransformDirection(inputDirection);

            // Project onto tangent plane
            inputDirection -= Vector3.Dot(inputDirection, normal) * normal;
            inputDirection.Normalize();

            movementDirection = inputDirection;

            // Apply movement velocity
            Vector3 desiredVelocity = movementDirection * moveSpeed;
            desiredVelocity.y = rb.velocity.y; // Preserve vertical velocity (gravity/jumping)
            rb.velocity = desiredVelocity;

            // Rotate towards movement direction
            if (movementDirection.sqrMagnitude > 0.01f)
            {
                Quaternion targetRotation = Quaternion.LookRotation(movementDirection, normal);
                rb.MoveRotation(Quaternion.Slerp(rb.rotation, targetRotation, rotationSpeed * Time.fixedDeltaTime));
            }
        }
        else
        {
            // Handle falling or no contact
        }
    }
}
```

