import React, { useState, useEffect } from 'react';
import { Text, TouchableOpacity, View, LayoutAnimation, StyleSheet } from 'react-native';

const ExpandableText = ({ text, style, ...props }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [limitedHeight, setLimitedHeight] = useState(0);
  const [fullHeight, setFullHeight] = useState(0);
  const [isTruncated, setIsTruncated] = useState(false);

  const handleLimitedLayout = (event) => {
    const { height } = event.nativeEvent.layout;
    setLimitedHeight(height);
  };

  const handleFullLayout = (event) => {
    const { height } = event.nativeEvent.layout;
    setFullHeight(height);
  };

  useEffect(() => {
    if (limitedHeight && fullHeight) {
      setIsTruncated(limitedHeight < fullHeight);
    }
  }, [limitedHeight, fullHeight]);

  return (
    <View style={styles.container}>
      <Text
        numberOfLines={isExpanded ? null : 1}
        style={[styles.text, style]}
        {...props}
      >
        {text}
      </Text>
      {isTruncated && (
        <TouchableOpacity
          style={styles.button}
          onPress={() => {
            LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
            setIsExpanded(!isExpanded);
          }}
        >
          <Text style={styles.buttonText}>
            {isExpanded ? 'See less' : 'See more'}
          </Text>
        </TouchableOpacity>
      )}
      <Text
        style={[styles.hiddenText, style]}
        onLayout={handleLimitedLayout}
        numberOfLines={1}
      >
        {text}
      </Text>
      <Text
        style={[styles.hiddenText, style]}
        onLayout={handleFullLayout}
      >
        {text}
      </Text>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    position: 'relative',
  },
  text: {
    marginBottom: 8, // Space between text and button
  },
  button: {
    alignSelf: 'flex-start',
    paddingVertical: 4,
  },
