import { defineStore } from 'pinia';

export const useRowsStore = defineStore('rows', {
  state: () => ({
    rows: [],
    totalRows: null, // if your API returns the total available count
    loading: false
  }),
  actions: {
    async fetchRows(start, count) {
      // Prevent multiple concurrent fetches.
      if (this.loading) return;

      this.loading = true;
      try {
        // Replace the URL below with your actual API endpoint.
        const response = await fetch(`https://api.example.com/rows?start=${start}&count=${count}`);
        const data = await response.json();
        // If the API returns a “total” value, store it.
        if (this.totalRows === null && data.total !== undefined) {
          this.totalRows = data.total;
        }
        // Append the new rows (assuming data.rows is an array)
        this.rows.push(...data.rows);
      } catch (error) {
        console.error("Error fetching rows:", error);
      } finally {
        this.loading = false;
      }
    }
  }
});

