namespace StudentMaintenance
{
    public static class StudentDB
    {
        private const string Dir = @"C:\C#\files\Students\";
        private const string Path = Dir + "Students.dat";

        public static void SaveStudents(List<Student> students)
        {
            using (BinaryWriter binaryOut = new BinaryWriter(
                new FileStream(Path, FileMode.Create, FileAccess.Write)))
            {
                foreach (Student s in students)
                {
                    binaryOut.Write(s.StudentID);
                    binaryOut.Write(s.Name);
                    binaryOut.Write(s.GPA);
                }
            }
        }

        public static List<Student> GetStudents()
        {
            List<Student> students = new List<Student>();

            if (!Directory.Exists(Dir))
                Directory.CreateDirectory(Dir);

            using (BinaryReader binaryIn = new BinaryReader(
                new FileStream(Path, FileMode.OpenOrCreate, FileAccess.Read)))
            {
                while (binaryIn.PeekChar() != -1)
                {
                    int id = binaryIn.ReadInt32();
                    string name = binaryIn.ReadString();
                    decimal gpa = binaryIn.ReadDecimal();

                    students.Add(new Student { StudentID = id, Name = name, GPA = gpa });
                }
            }

            return students;
        }
    }
}
