#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    int t;
    cin >> t;
    while(t--) {
        int n;
        cin >>n;
        vector<int> x(n);
        for(int i=0; i<n; i++) cin >>x[i];
        vector<int> gaps(n-1);
        for(int i=0; i <n-1; ++i) gaps[i] = x[i+1] - x[i];
        vector<int> min_gap(n);
        for(int j=0; j <n; j++) {
            int left_gap = (j>0) ? gaps[j-1] : INT_MAX;
            int right_gap = (j <n-1) ? gaps[j] : INT_MAX;
            min_gap[j] = min(left_gap, right_gap);
        }
        int left = -1e9;
        int right = 1e9;
        for(int j=0; j <n; ++j) {
            int current_left = x[j] - min_gap[j];
            int current_right = x[j] + min_gap[j];
            if(current_left > left) left = current_left;
            if(current_right < right) right = current_right;
        }
        if(left > right) {
            cout << "NO\n";
            continue;
        }
        unordered_set<int> s(x.begin(), x.end());
        bool found = false;
        for(int x_val = left; x_val <= right; x_val++) {
            if(s.find(x_val) == s.end()) {
                found = true;
                break;
            }
        }
        cout << (found ? "YES" : "NO") << '\n';
    }
    return 0;
}
