Here's a step-by-step guide to implement the Arduino Nano project for your model railroad house lighting automation with an OLED display and TV flicker simulation:

---

### **Step 1: Gather Components**
- **Arduino Nano**
- **0.96" I2C OLED Display** (128x64 pixels)
- **DS3231 Real-Time Clock (RTC) Module**
- **4 LEDs** (for lights and TVs) + **Current-limiting resistors** (220-330Ω)
- **2 Push Buttons** with pull-up resistors
- **Breadboard & Jumper Wires**
- **9V Battery/Power Supply** for the Nano and RTC

---

### **Step 2: Hardware Setup**
#### **Connections:**
| Component            | Arduino Nano Pin |
|----------------------|------------------|
| OLED SDA             | A4               |
| OLED SCL             | A5               |
| OLED VCC             | 5V               |
| OLED GND             | GND              |
| DS3231 SDA           | A4               |
| DS3231 SCL           | A5               |
| DS3231 VCC           | 5V               |
| DS3231 GND           | GND              |
| Living Room Lights   | Digital 2         |
| Bedroom Lights       | Digital 3         |
| Living Room TV       | Digital 4         |
| Bedroom TV           | Digital 5         |
| Button 1 (Ratio)     | Digital 7         |
| Button 2 (Nighttime) | Digital 8         |

**Notes:**
- Use **220Ω resistors** for LEDs to prevent burning out.
- The OLED and DS3231 share the same I2C bus (SDA/SCL pins).

---

### **Step 3: Install Required Libraries**
1. Open Arduino IDE.
2. Go to **Sketch > Include Library > Manage Libraries**.
3. Install the following libraries:
   - **Adafruit SSD1306** (for OLED)
   - **RTClib** (for DS3231)

---

### **Step 4: Code Implementation**
Copy the following code into your Arduino IDE:

```cpp
#include <Wire.h>
#include <Adafruit_SSD1306.h>
#include "RTClib.h"

// OLED Display Configuration
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

// Pins
#define LIVING_ROOM_LIGHTS 2
#define BEDROOM_LIGHTS 3
#define LIVING_ROOM_TV 4
#define BEDROOM_TV 5
#define BUTTON1_PIN 7 // Adjust Time Ratio
#define BUTTON2_PIN 8 // Toggle Nighttime Duration

// RTC
RTC_DS3231 rtc;

// Settings
int timeRatio = 6; // Initial time ratio (6:1)
bool nighttimeEnabled = true; // Bedroom TV stays on for 2 hours at night

// Flicker Variables
unsigned long prevFlicker_LR = 0, prevFlicker_BR = 0;
int flickerInterval_LR = 0, flickerInterval_BR = 0;

void setup() {
  // Initialize Pins
  pinMode(LIVING_ROOM_LIGHTS, OUTPUT);
  pinMode(BEDROOM_LIGHTS, OUTPUT);
  pinMode(LIVING_ROOM_TV, OUTPUT);
  pinMode(BEDROOM_TV, OUTPUT);
  pinMode(BUTTON1_PIN, INPUT_PULLUP);
  pinMode(BUTTON2_PIN, INPUT_PULLUP);

  // Initialize OLED
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    while (1); // Error: Display not found
  }
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(WHITE);
  display.display();

  // Initialize RTC
  if (!rtc.begin()) {
    while (1); // Error: RTC not found
  }
}

void loop() {
  // Get Current Real Time
  DateTime now = rtc.now();
  int real_sec = now.second();
  int real_min = now.minute();
  int real_hour = now.hour();

  // Calculate Model Time
  int real_seconds = real_hour * 3600 + real_min * 60 + real_sec;
  int model_seconds = real_seconds * timeRatio;
  int model_hours = model_seconds / 3600 % 24;
  int model_minutes = (model_seconds % 3600) / 60;

  // Update Lights/TVs
  updateLights(model_hours, model_minutes);
  updateTVs(model_hours, model_minutes);

  // Handle Button Inputs
  checkButton1();
  checkButton2();

  // Update OLED Display
  display.clearDisplay();
  display.setCursor(0, 0);
  display.print("Time: ");
  display.print(model_hours);
  display.print(":");
  display.print(model_minutes < 10 ? "0" : "");
  display.println(model_minutes);
  display.println(getCurrentEvent(model_hours, model_minutes));
  display.display();

  // Flicker Effect for TVs
  applyFlicker(LIVING_ROOM_TV, prevFlicker_LR, flickerInterval_LR);
  applyFlicker(BEDROOM_TV, prevFlicker_BR, flickerInterval_BR);

  delay(200); // Refresh interval
}

// Light Control Functions
void updateLights(int h, int m) {
  // Living Room Lights (7 AM - 9 PM)
  digitalWrite(LIVING_ROOM_LIGHTS, (h >= 7 && h < 21) ? HIGH : LOW);

  // Bedroom Lights (7 AM - 10 PM)
  digitalWrite(BEDROOM_LIGHTS, (h >= 7 && h < 22) ? HIGH : LOW);
}

// TV Control Functions
void updateTVs(int h, int m) {
  // Living Room TV (7 PM - Midnight)
  digitalWrite(LIVING_ROOM_TV, (h >= 19) ? HIGH : LOW);

  // Bedroom TV (6-7 AM for news, 10 PM - Midnight or 11 PM if nighttime is toggled)
  bool bedTVOn = false;
  if ((h >= 6 && h < 7) || 
      (h >= 22 && h < 24) || 
      (h == 24 && m < 60)) {
    bedTVOn = true;
  } else if (!nighttimeEnabled && h == 22 && m < 60) {
    bedTVOn = true;
  }
  digitalWrite(BEDROOM_TV, bedTVOn ? HIGH : LOW);
}

// Flicker Effect
void applyFlicker(int pin, unsigned long &prevTime, int &interval) {
  unsigned long currentMillis = millis();
  if (digitalRead(pin) == HIGH) { // Only flicker if TV is scheduled to be on
    if (currentMillis - prevTime >= interval) {
      prevTime = currentMillis;
      // Randomly toggle LED with 10% off chance
      if (random(0, 100) > 10) {
        digitalWrite(pin, HIGH);
      } else {
        digitalWrite(pin, LOW);
      }
      interval = random(50, 200); // Random interval between 50-200ms
    }
  }
}

// Button Handling
void checkButton1() { // Adjust Time Ratio
  if (digitalRead(BUTTON1_PIN) == LOW) {
    delay(200); // Debounce
    if (digitalRead(BUTTON1_PIN) == LOW) {
      timeRatio = (timeRatio % 10) + 1; // Cycle 1-10
      delay(500); // Prevent multiple triggers
    }
  }
}

void checkButton2() { // Toggle Nighttime Duration
  if (digitalRead(BUTTON2_PIN) == LOW) {
    delay(200); // Debounce
    if (digitalRead(BUTTON2_PIN) == LOW) {
      nighttimeEnabled = !nighttimeEnabled;
      delay(500); // Prevent multiple triggers
    }
  }
}

// Event Display Helper
String getCurrentEvent(int h, int m) {
  String event = "None";
  if (h >= 7 && h < 21) {
    event = "Living Room Lights On";
  } else if (h >= 22 && h < 24) {
    event = "Bedroom TV Night Mode";
  } else if (h >= 6 && h < 7) {
    event = "Morning News (Bedroom TV)";
  }
  return event;
}
```

---

### **Step 5: Upload and Test**
1. Connect the Arduino Nano to your computer.
2. Select the correct board and port in Arduino IDE.
3. Upload the code.
4. Power the system (ensure the RTC is powered to retain time).

---

### **Step 6: Usage**
- **OLED Display**: Shows the accelerated time and current event (e.g., "Living Room Lights On").
- **Button 1**: Press to cycle the time ratio (1:1, 2:1, ..., 10:1).
- **Button 2**: Press to toggle nighttime duration (2 hours vs. 1 hour for bedroom TV).
- **TV Flicker**: Bedroom/Living Room TVs blink softly when on.

---

### **Step 7: Adjustments**
- **Time Ratio**: Use Button 1 to speed up/slow down time.
- **Nighttime Duration**: Use Button 2 to shorten bedroom TV runtime.
- **Schedule Customization**: Modify the `updateLights()` and `updateTVs()` functions in the code to adjust timings.

---

This setup mimics daily activities with accelerated time, TV flicker effects, and adjustable parameters. Enjoy your model railroad simulation!

