---

### Step 1: Create the Flake Configuration Directory
Create a directory for your NixOS configuration (replace `your-username` with your actual username):
```bash
mkdir -p ~/.config/nixos-flake
cd ~/.config/nixos-flake
```

---

### Step 2: Create `flake.nix`
This file defines the NixOS system and Home Manager configurations:
```nix
{
  description = "My NixOS + Home Manager configuration";
  inputs = {
    nixpkgs = { url = "github:NixOS/nixpkgs/nixos-unstable"; };
    home-manager = {
      url = "github:nix-community/home-manager";
      inputs.nixpkgs.follows = "nixpkgs";
    };
  };
  outputs = { self, nixpkgs, home-manager, ... }:
    let
      system = "x86_64-linux";
      username = "your-username"; # Replace with your username
      hostname = "my-machine"; # Replace with your hostname (e.g., output of `hostname`)
    in
    {
      nixosConfigurations."${hostname}" = nixpkgs.lib.nixosSystem {
        system = system;
        modules = [
          ./nixos/configuration.nix
          (home-manager.modules.home-manager {
            users.username = username;
            configuration = import ./home/home.nix;
          })
        ];
      };
      homeConfigurations."${username}" = home-manager.lib.homeManagerConfiguration {
        users.username = username;
        configuration = import ./home/home.nix;
      };
    };
}
```

---

### Step 3: Create `nixos/configuration.nix`
This file sets up the system configuration (GNOME, services, and packages):
```nix
{ config, pkgs, ... }:

{
  # Use GNOME with Wayland
  services.xserver = {
    enable = true;
    layout = "us"; # Replace with your keyboard layout (e.g., "de")
    desktopManager.gnome.enable = true;
    desktopManager.gnome.session = "wayland";
  };

  # Enable GDM as the display manager
  services.gdm.enable = true;

  # Install essential packages
  environment.systemPackages = with pkgs; [
    # Applications
    gnome.gnome3
    neovim
    code
    zed
    brave-bin
    bitwarden

    # Standard tools (10+)
    curl
    git
    tmux
    python3
    wget
    rsync
    openssh
    jq
    ripgrep
  ];

  # User configuration
  users.users."${lib.optionalString config.lib.username}your-username" = {
    isNormalUser = true;
    extraGroups = [ "wheel" "networkmanager" "audio" "video" ];
  };

  # Enable Wayland
  environment.wayland.enable = true;

  # Additional settings
  networking.hostName = "my-machine"; # Replace with your hostname
}
```

---

### Step 4: Create `home/home.nix`
This file configures user-specific settings via Home Manager:
```nix
{ config, pkgs, ... }:

{
  # Shell configuration
  programs.zsh.enable = true;
  programs.zsh.shellInit = ''
    source $HOME/.zshrc
  '';

  # Neovim setup
  programs.neovim = {
    enable = true;
