```typescript
import React, { useState, useRef, useMemo } from 'react';
import './InputDropdown.css';

type Option = {
  label: string;
  value: string | number;
};

type Props = {
  options: Option[];
  placeholder?: string;
};

const InputDropdown: React.FC<Props> = ({ options, placeholder }) => {
  const [value, setValue] = useState('');
  const [filteredOptions, setFilteredOptions] = useState<Option[]>([]);
  const debounceTimer = useRef<number>();

  // Memoized Set of labels for O(1) validity checks
  const labelsSet = useMemo(() => new Set(options.map(opt => opt.label)), [options]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const inputValue = e.target.value;
    setValue(inputValue);

    // Clear previous timeout
    if (debounceTimer.current) {
      window.clearTimeout(debounceTimer.current);
    }

    // Debounce filtering
    debounceTimer.current = window.setTimeout(() => {
      const filtered = options.filter(opt => 
        opt.label.toLowerCase().includes(inputValue.toLowerCase())
      );
      setFilteredOptions(filtered);
    }, 300);
  };

  const computedIsValid = value === '' || labelsSet.has(value);

  const handleSelectOption = (selectedLabel: string) => {
    setValue(selectedLabel);
    setFilteredOptions([]); // Hide dropdown after selection
  };

  return (
    <div className="input-container">
      <input
        type="text"
        value={value}
        onChange={handleInputChange}
        className={computedIsValid ? 'valid' : 'invalid'}
        placeholder={placeholder}
      />
      {filteredOptions.length > 0 && (
        <div className="dropdown">
          <ul>
            {filteredOptions.map(opt => (
              <li
                key={opt.value}
                onClick={() => handleSelectOption(opt.label)}
                className="dropdown-item"
              >
                {opt.label}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
};

export default InputDropdown;
