  | { success: true; value: T }
  | { success: false; error: E };

──────────────────────────────────────────────
• Create a synchronous wrapper function:

──────────────────────────────────────────────
export function tryCatch<T>(fn: () => T): Result<T> {
  try {
    const value = fn();
    return { success: true, value };
  } catch (error) {
    return { success: false, error };
  }
}

