  // Some synchronous code that might throw
  return "Hello, world!";
});

if (resultSync.success) {
  console.log("Value:", resultSync.value);
} else {
  console.error("Error:", resultSync.error);
}

(async () => {
  const resultAsync = await tryCatchAsync(async () => {
    // Some asynchronous code that might reject or throw
    return await Promise.resolve("Async hello!");
  });

  if (resultAsync.success) {
    console.log("Value:", resultAsync.value);
  } else {
    console.error("Error:", resultAsync.error);
  }
})(); 

